"""Portable site gate for a two-direction shared center turn lane.

The caller must populate this packet from an original Native map and a reviewed
public-highway source. A lane label alone cannot establish the statute's design.
"""

from math import hypot, isfinite


def _xy(value):
    if not isinstance(value, (list, tuple)) or len(value) != 2:
        raise ValueError("missing planar waypoint")
    pair = tuple(float(v) for v in value)
    if not all(isfinite(v) for v in pair):
        raise ValueError("non-finite waypoint")
    return pair


def _direction(lane):
    points = lane.get("centreline_xy_m")
    if not isinstance(points, list) or len(points) < 2:
        raise ValueError("lane needs original centreline")
    start, end = _xy(points[0]), _xy(points[-1])
    dx, dy = end[0] - start[0], end[1] - start[1]
    magnitude = hypot(dx, dy)
    if magnitude < 10:
        raise ValueError("lane segment too short to establish direction")
    return dx / magnitude, dy / magnitude


def validate_site(packet):
    if not packet.get("native_map_source") or not packet.get("highway_review_source"):
        raise ValueError("site requires Native map and public-highway review sources")
    if packet.get("public_highway_confirmed") is not True:
        raise ValueError("public-highway status unverified")
    lanes = packet.get("lanes")
    if not isinstance(lanes, list) or len(lanes) < 3:
        raise ValueError("site requires original lane inventory")
    ids = [lane.get("id") for lane in lanes]
    if len(set(ids)) != len(ids) or not all(ids):
        raise ValueError("lane identifiers missing or duplicated")
    centers = [lane for lane in lanes if lane.get("center_turn_lane") is True]
    if len(centers) != 1:
        raise ValueError("highway must have exactly one shared center turn lane")
    center = centers[0]
    if center.get("exclusive_turn_use") is not True or center.get("permitted_turn_directions") != ["negative", "positive"]:
        raise ValueError("bidirectional exclusive turning use unverified")
    corridor = center.get("road_id")
    if not corridor or any(lane.get("road_id") != corridor for lane in lanes if lane.get("receiving_through") or lane.get("opposing_through")):
        raise ValueError("through lanes must belong to same highway")
    receiving = [lane for lane in lanes if lane.get("receiving_through") is True]
    opposing = [lane for lane in lanes if lane.get("opposing_through") is True]
    if len(receiving) != 1 or len(opposing) != 1:
        raise ValueError("one receiving and one opposing through lane required")
    a, b = _direction(receiving[0]), _direction(opposing[0])
    if a[0] * b[0] + a[1] * b[1] > -0.8:
        raise ValueError("through directions are not opposing")
    if packet.get("entry_maneuver") != "left_turn_onto_highway":
        raise ValueError("entry is not left turn onto highway")
    if packet.get("entry_target_lane_id") != center["id"] or packet.get("merge_target_lane_id") != receiving[0]["id"]:
        raise ValueError("entry and merge targets mismatch verified lanes")
    return {"center_lane_id": center["id"], "receiving_lane_id": receiving[0]["id"],
            "opposing_lane_id": opposing[0]["id"], "road_id": corridor,
            "native_map_source": packet["native_map_source"],
            "highway_review_source": packet["highway_review_source"]}

"""Independent CPU comparison of original measured center-lane travel.

This checks packet completeness and controlled differences. It does not make a
statutory verdict or accept a physical recording.
"""

from math import isfinite


def audit_numeric_triple(rows):
    expected = ("below_50ft", "at_50ft", "above_50ft")
    if set(rows) != set(expected):
        raise ValueError("comparison requires exact below/at/above cases")
    fixed = ("native_map_sha256", "highway_review_sha256", "lane_design_sha256",
             "entry_route_sha256", "receiving_vehicle_route_sha256", "camera_plan_sha256")
    for suffix in expected:
        row = rows[suffix]
        if not row.get("original_trace_source") or not row.get("original_trace_sha256"):
            raise ValueError("missing original trace binding: " + suffix)
        if row.get("merge_observed") is not True or row.get("censored") is not False:
            raise ValueError("numeric case needs observed merge: " + suffix)
        if not all(row.get(key) for key in fixed):
            raise ValueError("missing fixed condition: " + suffix)
        distance = row.get("distance_ft")
        if not isinstance(distance, (float, int)) or not isfinite(distance) or distance < 0:
            raise ValueError("invalid original distance: " + suffix)
        if row.get("boundary_ft") != 50.0:
            raise ValueError("wrong statutory boundary: " + suffix)
    for key in fixed:
        if len({rows[suffix][key] for suffix in expected}) != 1:
            raise ValueError("fixed condition differs: " + key)
    if len({rows[suffix]["original_trace_sha256"] for suffix in expected}) != 3:
        raise ValueError("case traces must be distinct")
    measured = {suffix: rows[suffix]["distance_ft"] for suffix in expected}
    # This tolerance is only a capture probe for the authored at-boundary case.
    # It does not resolve vehicle reference-point or legal interpretation.
    if not (measured["below_50ft"] < 50.0 and
            abs(measured["at_50ft"] - 50.0) <= 0.25 and
            measured["above_50ft"] > 50.0 and
            measured["below_50ft"] < measured["at_50ft"] < measured["above_50ft"]):
        raise ValueError("original measurements do not realize below/at/above probes")
    return {"comparison_id": "post_turn_center_lane_distance", "fixed_conditions_verified": list(fixed),
            "measured_distance_ft": measured, "at_boundary_probe_tolerance_ft": 0.25,
            "original_sources": {suffix: rows[suffix]["original_trace_source"] for suffix in expected},
            "legal_judgment": None}


def audit_merge_observation(merged, no_merge):
    for row in (merged, no_merge):
        if not row.get("original_trace_source") or not row.get("original_trace_sha256"):
            raise ValueError("missing original trace binding")
    for key in ("native_map_sha256", "highway_review_sha256", "lane_design_sha256",
                "entry_route_sha256", "receiving_vehicle_route_sha256", "camera_plan_sha256"):
        if not merged.get(key) or merged[key] != no_merge.get(key):
            raise ValueError("fixed condition differs: " + key)
    if merged.get("merge_observed") is not True or merged.get("censored") is not False:
        raise ValueError("reference merge not observed")
    if no_merge.get("merge_observed") is not False or no_merge.get("censored") is not True or no_merge.get("merge_frame") is not None:
        raise ValueError("no-merge case must be censored")
    return {"comparison_id": "merge_observation", "fixed_conditions_verified": True,
            "merge_observed": [True, False], "legal_judgment": None}

"""Read-only audit of original saved sources for NRS 484B.223(3)(c).

This checks provenance and measurement arithmetic. It cannot establish a road's
legal status, camera visibility, physical motion, or statutory compliance.
"""

import hashlib
import importlib.util
import json
from math import isclose, isfinite
from pathlib import Path, PurePosixPath


_SPEC = importlib.util.spec_from_file_location(
    "center_lane_measurement_for_audit", Path(__file__).with_name("center_lane_measurement.py")
)
_MEASUREMENT = importlib.util.module_from_spec(_SPEC)
_SPEC.loader.exec_module(_MEASUREMENT)
VIEWS = ("overview", "approach", "reference_corner", "driver_reference")


def _read_bound_json(root, binding):
    if not isinstance(binding, dict):
        raise ValueError("missing source binding")
    relative = binding.get("path")
    digest = binding.get("sha256")
    if not isinstance(relative, str) or not relative or not isinstance(digest, str) or len(digest) != 64:
        raise ValueError("incomplete source binding")
    path = PurePosixPath(relative)
    if path.is_absolute() or ".." in path.parts or relative.startswith("./"):
        raise ValueError("source path escapes attempt")
    source = (root / relative).resolve()
    if not source.is_relative_to(root.resolve()) or not source.is_file():
        raise ValueError("missing original source: " + relative)
    raw = source.read_bytes()
    if hashlib.sha256(raw).hexdigest() != digest.lower():
        raise ValueError("source hash mismatch: " + relative)
    return json.loads(raw.decode("utf-8"))


def audit_saved_delivery(attempt_root, receipt):
    """Recompute a delivered case from its hash-bound original saved trace.

    The attempt contains JSON for the Native body/lane trace, independent site
    review and lane-design sources, and a frame map. The receipt only names and
    hashes those files; it cannot replace them with its own values.
    """
    root = Path(attempt_root).resolve()
    if not receipt.get("case_id") or not receipt.get("attempt_id"):
        raise ValueError("missing case or attempt identity")
    trace = _read_bound_json(root, receipt.get("original_trace"))
    for field in ("highway_context_source", "lane_design_source"):
        source = trace.get(field)
        if source != receipt.get(field):
            raise ValueError("trace and receipt source binding differ: " + field)
        _read_bound_json(root, source)
    if trace.get("source") != {"path": receipt["original_trace"]["path"]}:
        raise ValueError("trace self-binding differs from original trace")
    # A file cannot contain its own SHA256. The original trace's self-reference
    # therefore records its path only; the receipt supplies the content hash.
    frame_map = _read_bound_json(root, receipt.get("frame_map_source"))
    if frame_map.get("fps") != 20:
        raise ValueError("original frame map must use 20 Hz")
    frames = [row.get("frame") for row in trace.get("samples", [])]
    mappings = frame_map.get("frames")
    if not isinstance(mappings, list) or [row.get("frame") for row in mappings] != frames:
        raise ValueError("original frame map does not join trace frames")
    for row in mappings:
        sources = row.get("camera_sources")
        if not isinstance(sources, dict) or set(sources) != set(VIEWS) or not all(sources.values()):
            raise ValueError("incomplete four-camera frame mapping")
        camera_hashes = row.get('camera_sha256')
        if camera_hashes is not None:
            if not isinstance(camera_hashes, dict) or set(camera_hashes) != set(VIEWS):
                raise ValueError('incomplete original camera hashes')
            for view in VIEWS:
                relative = sources[view]
                if not isinstance(relative, str) or Path(relative).is_absolute() or '..' in Path(relative).parts or relative.startswith('./'):
                    raise ValueError('camera source path escapes attempt')
                camera_file = (root / relative).resolve()
                if not camera_file.is_relative_to(root) or not camera_file.is_file():
                    raise ValueError('missing original camera source')
                if hashlib.sha256(camera_file.read_bytes()).hexdigest() != camera_hashes[view]:
                    raise ValueError('camera source hash mismatch')
    measured = _MEASUREMENT.measure_center_lane_distance(trace)
    delivered = receipt.get("delivered_measurement")
    if not isinstance(delivered, dict):
        raise ValueError("missing delivered measurement")
    for key in ("turn_frame", "merge_frame", "merge_observed", "censored", "boundary_ft"):
        if delivered.get(key) != measured[key]:
            raise ValueError("delivered event or boundary mismatch: " + key)
    for key in ("distance_m", "distance_ft"):
        value = delivered.get(key)
        if not isinstance(value, (int, float)) or not isfinite(value) or not isclose(value, measured[key], rel_tol=0, abs_tol=1e-6):
            raise ValueError("delivered distance mismatch: " + key)
    return {"case_id": receipt["case_id"], "attempt_id": receipt["attempt_id"],
            "original_trace_sha256": receipt["original_trace"]["sha256"],
            "frame_map_sha256": receipt["frame_map_source"]["sha256"],
            "verified_frame_count": len(frames), "measured": measured,
            "physical_acceptance": None, "legal_judgment": None}

"""Independent full decode of saved original four-camera PNG frame sources."""

import hashlib
import json
from pathlib import Path

from PIL import Image


DIMENSIONS = {'overview': (1920, 1080), 'approach': (1280, 720),
              'reference_corner': (1280, 720), 'driver_reference': (1280, 720)}


def audit_original_pngs(attempt_root, frame_map_binding, expected_frames, dimensions=None):
    root = Path(attempt_root).resolve()
    expected = DIMENSIONS if dimensions is None else dimensions
    if not isinstance(expected, dict) or set(expected) != set(DIMENSIONS):
        raise ValueError('incomplete expected four-camera dimensions')
    if not isinstance(frame_map_binding, dict) or frame_map_binding.get('path') != 'native/frame_map.json':
        raise ValueError('missing fixed original frame map binding')
    path = root / 'native/frame_map.json'
    raw = path.read_bytes()
    if hashlib.sha256(raw).hexdigest() != frame_map_binding.get('sha256'):
        raise ValueError('original frame map hash mismatch')
    frame_map = json.loads(raw.decode('utf-8'))
    rows = frame_map.get('frames')
    if frame_map.get('fps') != 20 or not isinstance(rows, list) or len(rows) != expected_frames:
        raise ValueError('incomplete original 20 Hz frame map')
    seen = set()
    previous = None
    decoded = 0
    for row in rows:
        frame = row.get('frame')
        if type(frame) is not int or (previous is not None and frame != previous + 1):
            raise ValueError('noncontiguous original camera frame')
        previous = frame
        sources = row.get('camera_sources')
        hashes = row.get('camera_sha256')
        if not isinstance(sources, dict) or not isinstance(hashes, dict) or set(sources) != set(expected) or set(hashes) != set(expected):
            raise ValueError('incomplete original four-camera source map')
        for view in expected:
            relative = sources[view]
            if relative != 'camera/' + view + '/%06d.png' % frame or relative in seen:
                raise ValueError('substituted or duplicate original camera path')
            seen.add(relative)
            source = (root / relative).resolve()
            if not source.is_relative_to(root) or not source.is_file():
                raise ValueError('missing original camera source')
            if hashlib.sha256(source.read_bytes()).hexdigest() != hashes[view]:
                raise ValueError('original camera source hash mismatch')
            with Image.open(source) as image:
                image.load()
                if image.format != 'PNG' or image.mode != 'RGB' or image.size != tuple(expected[view]):
                    raise ValueError('original camera PNG profile mismatch: ' + view)
            decoded += 1
    return {'frame_count': len(rows), 'decoded_camera_images': decoded,
            'frame_map_sha256': frame_map_binding['sha256'], 'physical_acceptance': None}

"""Portable route follower for the left-turn, center-lane and merge phases.

The path comes from a source-verified Native site. This controller commands
motion only; original measurements decide what the vehicle actually did.
"""

from math import atan2, hypot, pi


def _wrap(angle):
    return (angle + pi) % (2 * pi) - pi


class TurnMergeController:
    def __init__(self, route_xy_m, target_speed_mps=4.0, waypoint_radius_m=1.5):
        if not isinstance(route_xy_m, list) or len(route_xy_m) < 4:
            raise ValueError("route needs entry, center-lane and through-lane waypoints")
        self.route = [tuple(map(float, point)) for point in route_xy_m]
        if any(len(point) != 2 for point in self.route):
            raise ValueError("waypoints must be planar")
        if target_speed_mps <= 0 or waypoint_radius_m <= 0:
            raise ValueError("speed and waypoint radius must be positive")
        self.target_speed = float(target_speed_mps)
        self.radius = float(waypoint_radius_m)
        self.index = 0

    def command(self, x_m, y_m, yaw_rad, speed_mps):
        while self.index < len(self.route) - 1 and hypot(self.route[self.index][0] - x_m, self.route[self.index][1] - y_m) <= self.radius:
            self.index += 1
        goal_x, goal_y = self.route[self.index]
        heading_error = _wrap(atan2(goal_y - y_m, goal_x - x_m) - yaw_rad)
        steer = max(-1.0, min(1.0, heading_error / 0.65))
        speed_error = self.target_speed - speed_mps
        throttle = max(0.0, min(0.55, 0.22 * speed_error))
        brake = max(0.0, min(0.6, -0.3 * speed_error))
        arrived = self.index == len(self.route) - 1 and hypot(goal_x - x_m, goal_y - y_m) <= self.radius
        if arrived:
            throttle, brake = 0.0, 0.6
        return {"steer": steer, "throttle": throttle, "brake": brake,
                "waypoint_index": self.index, "route_complete": arrived}

    def apply(self, vehicle, x_m, y_m, yaw_rad, speed_mps, control_factory=None):
        command = self.command(x_m, y_m, yaw_rad, speed_mps)
        if control_factory is None:
            import carla  # Loaded only during an authorized local Native run.
            control_factory = carla.VehicleControl
        vehicle.apply_control(control_factory(throttle=command["throttle"],
                                              steer=command["steer"], brake=command["brake"]))
        return command
